package servicio;
import api.publica.PagoClienteDTO.*;import dao.OrdenPagoDAO;import dao.OrdenPagoDAOMySQL;import java.time.*;import java.util.*;import negocio.*;
public class ConsultaOrdenPagoClienteService {private final OrdenPagoDAO dao;private final Clock clock;public ConsultaOrdenPagoClienteService(){this(new OrdenPagoDAOMySQL(),Clock.systemDefaultZone());}public ConsultaOrdenPagoClienteService(OrdenPagoDAO d,Clock c){if(d==null||c==null)throw new IllegalArgumentException("Las dependencias son obligatorias.");dao=d;clock=c;}public OrdenPagoPublica convertir(OrdenPago o){if(o==null)return null;long restantes=o.getFechaExpiracion()==null?0:Math.max(0,Duration.between(LocalDateTime.now(clock),o.getFechaExpiracion()).toSeconds());boolean manual=o.getMetodo()==MetodoOrdenPago.TRANSFERENCIA_MANUAL;boolean reintento=Set.of(EstadoOrdenPago.RECHAZADA,EstadoOrdenPago.ERROR,EstadoOrdenPago.EXPIRADA).contains(o.getEstado());String mensaje=switch(o.getEstado()){case ESPERANDO_VERIFICACION->"El complejo verificará la transferencia desde la administración.";case ESPERANDO_PAGO->"Completá el pago para confirmar la cancha.";case PROCESANDO->"Estamos verificando la acreditación.";case APROBADA->"El pago fue acreditado.";case RECHAZADA->"El pago no pudo acreditarse.";case EXPIRADA->"La orden de pago venció.";default->"Estado de pago actualizado.";};return new OrdenPagoPublica(o.getId(),o.getReservaId(),o.getProveedor().name(),o.getMetodo().name(),o.getEstado().name(),o.getImporte(),o.getMoneda(),o.getFechaExpiracion(),restantes,!manual&&o.getEstado()==EstadoOrdenPago.ESPERANDO_PAGO,manual&&o.getEstado()==EstadoOrdenPago.ESPERANDO_VERIFICACION,reintento,!o.getEstado().esTerminal(),checkoutSeguro(o,restantes),mensaje);}private String checkoutSeguro(OrdenPago o,long restantes){if(o.getMetodo()!=MetodoOrdenPago.PAGO_ONLINE||o.getEstado()!=EstadoOrdenPago.ESPERANDO_PAGO||restantes<=0||o.getUrlPago()==null||o.getUrlPago().isBlank())return null;try{java.net.URI uri=java.net.URI.create(o.getUrlPago());return "https".equalsIgnoreCase(uri.getScheme())&&uri.getHost()!=null?uri.toString():null;}catch(RuntimeException e){return null;}}public HistorialOrdenes historial(long reservaId){return new HistorialOrdenes(reservaId,dao.listarPorReserva(reservaId).stream().map(this::convertir).toList());}}
